#!/usr/bin/env bash
set -euo pipefail

printf '%s\n' '$gitCommand = Get-Command git.exe -ErrorAction SilentlyContinue; $gitPath = if ($gitCommand) { $gitCommand.Source } else { $null }; if (-not $gitPath) { $winget = Get-Command winget.exe -ErrorAction SilentlyContinue; if (-not $winget) { throw "Git for Windows no está instalado y winget no está disponible." }; & $winget.Source install --id Git.Git --exact --source winget --scope machine --accept-source-agreements --accept-package-agreements; if ($LASTEXITCODE -ne 0) { throw "No se pudo instalar Git for Windows." }; $gitPath = Join-Path $env:ProgramFiles "Git\cmd\git.exe"; if (-not (Test-Path -LiteralPath $gitPath)) { throw "Git se instaló, pero no se encontró git.exe." } }; $env:Path = "$(Split-Path -Parent $gitPath);$env:Path"; & $gitPath pull --ff-only origin main; if ($LASTEXITCODE -ne 0) { throw "git pull falló." }; Set-ExecutionPolicy -Scope Process Bypass -Force; & ".\build-windows-pilot.ps1"'
